WITH cleaned AS (SELECT id, session_id, event_type, page, event_time, CASE WHEN page = '/cart' THEN 1 ELSE 0 END AS is_cart, COALESCE(page, 'DIRECT') AS page_filled FROM web_events WHERE event_time >= TIMESTAMP '2023-10-24 05:00:00') SELECT id, session_id, event_time, LAG(is_cart, 1) OVER (PARTITION BY page ORDER BY is_cart, id) AS prev_is_cart, SUM(is_cart) OVER (ORDER BY is_cart, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_is_cart, ROW_NUMBER() OVER (PARTITION BY page, session_id ORDER BY event_time DESC, id) AS row_seq, SUM(is_cart) OVER (ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_is_cart, LAG(is_cart, 2, 0) OVER (PARTITION BY event_type ORDER BY is_cart, id) AS prev_is_cart_2 FROM cleaned
